draw:
var beta = p.beta;
var gam = 1 / Math.sqrt(1 - beta * beta);
var pad = 30;
var font = "12px ui-sans-serif, system-ui, sans-serif";

// mirror separation in pixels, shrunk so two slanted legs still fit the canvas
var d = Math.min(0.34 * H, (W - 2 * pad) / (2 * beta * gam + 0.6));
var yTop = 0.26 * H;
var yBot = yTop + d;
var adv = beta * gam * d;          // horizontal advance per one-way leg
var x0 = pad + 10;

// mirrors at the three positions the clock occupies at the two turning points
ctx.lineWidth = 2;
var k;
for (k = 0; k < 3; k++) {
  var xc = x0 + k * adv;
  ctx.strokeStyle = k === 0 ? C.figure : C.faint;
  ctx.beginPath();
  ctx.moveTo(xc - 16, yBot); ctx.lineTo(xc + 16, yBot);
  ctx.moveTo(xc - 16, yTop); ctx.lineTo(xc + 16, yTop);
  ctx.stroke();
}

// the light path: down-up zigzag
ctx.lineWidth = 1.5;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
ctx.moveTo(x0, yBot);
ctx.lineTo(x0 + adv, yTop);
ctx.lineTo(x0 + 2 * adv, yBot);
ctx.stroke();
ctx.setLineDash([]);

// the vertical leg the clock's own frame sees
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(x0, yBot); ctx.lineTo(x0, yTop); ctx.stroke();

// animate the photon over one full round trip, then pause
var period = 3.2;
var ph = (t % period) / period;
var leg = ph * 2;
var px, py;
if (leg < 1) { px = x0 + adv * leg; py = yBot + (yTop - yBot) * leg; }
else { px = x0 + adv * leg; py = yTop + (yBot - yTop) * (leg - 1); }
if (leg > 2) { px = x0 + 2 * adv; py = yBot; }
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px, py, 4.5, 0, Math.PI * 2); ctx.fill();

// travelled part of the slanted path
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x0, yBot);
if (leg < 1) ctx.lineTo(px, py);
else { ctx.lineTo(x0 + adv, yTop); ctx.lineTo(px, py); }
ctx.stroke();

// labels
ctx.font = font;
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("d", x0 - 5, (yTop + yBot) / 2 + 4);
ctx.textAlign = "center";
ctx.fillText("v Δt", x0 + adv / 2, yBot + 18);
ctx.fillStyle = C.figure;
ctx.fillText("c Δt", x0 + adv / 2 - 14, (yTop + yBot) / 2 - 6);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("mirror", x0 + 20, yTop - 8);
ctx.fillText("mirror", x0 + 20, yBot + 18);

// base line marking the horizontal drift
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(x0, yBot + 8); ctx.lineTo(x0 + adv, yBot + 8); ctx.stroke();

var d0 = p.sep;
var tick0 = 2 * d0 / 3e8 * 1e9;
out.note = "gamma " + gam.toFixed(3) + "  |  round trip " + tick0.toFixed(1) +
  " ns on the clock itself, " + (gam * tick0).toFixed(1) + " ns in the lab";

var beta = p.beta;
var gam = 1 / Math.sqrt(1 - beta * beta);
var pad = 24;
var font = "12px ui-sans-serif, system-ui, sans-serif";

var Lpix = 0.22 * W;               // contracted train length on screen
var xm0 = 0.22 * W;                // flash point at time zero
var yT = 0.38 * H, yB = 0.62 * H;

// timings, in pixel units with c = 1 pixel per unit
var tBack = (Lpix / 2) / (1 + beta);
var tFront = (Lpix / 2) / (1 - beta);
var span = tFront * 1.25;
var tau = (t % 3.6) / 3.6 * span;

var xmid = xm0 + beta * tau;
var xr = xmid - Lpix / 2, xf = xmid + Lpix / 2;

// ground
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, yB + 22); ctx.lineTo(W, yB + 22); ctx.stroke();

// train
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.strokeRect(xr, yT, Lpix, yB - yT);

// photons
var xl = Math.max(xm0 - tau, xr);
var xg = Math.min(xm0 + tau, xf);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xl, (yT + yB) / 2, 4, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(xg, (yT + yB) / 2, 4, 0, Math.PI * 2); ctx.fill();

// flash origin
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(xm0, yT - 14); ctx.lineTo(xm0, yB + 22); ctx.stroke();
ctx.setLineDash([]);

// mark the ends once they are hit
ctx.font = font;
ctx.textAlign = "center";
if (tau >= tBack) {
  ctx.fillStyle = C.accent;
  ctx.fillRect(xr - 3, yT, 6, yB - yT);
  ctx.fillText("rear hit first", xr, yT - 8);
}
if (tau >= tFront) {
  ctx.fillStyle = C.accent;
  ctx.fillRect(xf - 3, yT, 6, yB - yT);
  ctx.fillText("front hit later", xf, yT - 8);
}

ctx.fillStyle = C.ink;
ctx.fillText("flash here", xm0, yB + 38);
ctx.textAlign = "left";
ctx.fillText("rear", xr + 6, yB - 8);
ctx.textAlign = "right";
ctx.fillText("front", xf - 6, yB - 8);
ctx.textAlign = "center";
ctx.fillStyle = C.figure;
ctx.fillText("train moves right at " + beta.toFixed(2) + "c", xmid, yT - 26);

var L0 = p.length;
var off = beta * L0 / 3e8 * 1e6;
out.note = "proper length " + L0.toFixed(0) + " m, measured on the ground " +
  (L0 / gam).toFixed(1) + " m  |  rear clock reads ahead by " + off.toFixed(2) + " us";

var beta = p.beta;
var gam = 1 / Math.sqrt(1 - beta * beta);
var h = p.height * 1000;
var tau0 = 2.2e-6;
var c = 3e8;
var Lclass = beta * c * tau0;        // mean travel with no dilation
var Lrel = gam * Lclass;             // mean travel with dilation
var fRel = Math.exp(-h / Lrel);
var fCla = Math.exp(-h / Lclass);

var pad = 34;
var x0 = pad + 40, x1 = W - pad;
var yTop = pad, yBot = H - pad - 6;
var font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = font;

// axes: vertical is altitude, horizontal is surviving fraction
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(x0, yTop); ctx.lineTo(x0, yBot); ctx.lineTo(x1, yBot);
ctx.stroke();

var Y = function (alt) { return yBot - (alt / h) * (yBot - yTop); };
var X = function (f) { return x0 + f * (x1 - x0); };

// survival curves, drawn downward from the creation altitude
var i, alt, f;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
for (i = 0; i <= 100; i++) {
  alt = h - h * i / 100;
  f = Math.exp(-(h - alt) / Lclass);
  i === 0 ? ctx.moveTo(X(f), Y(alt)) : ctx.lineTo(X(f), Y(alt));
}
ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 100; i++) {
  alt = h - h * i / 100;
  f = Math.exp(-(h - alt) / Lrel);
  i === 0 ? ctx.moveTo(X(f), Y(alt)) : ctx.lineTo(X(f), Y(alt));
}
ctx.stroke();

// a muon falling, looping
var ph = (t % 4) / 4;
var altNow = h * (1 - ph);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(x0 - 22, Y(altNow), 5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText(p.height.toFixed(0) + " km", x0 - 34, yTop + 5);
ctx.fillText("ground", x0 - 34, yBot + 4);
ctx.textAlign = "center";
ctx.fillText("fraction still undecayed", (x0 + x1) / 2, yBot + 20);
ctx.textAlign = "left";
ctx.fillStyle = C.accent;
ctx.fillText("with time dilation", X(0.08), yTop + 14);
ctx.fillStyle = C.rule;
ctx.fillText("classical prediction", X(0.08), yTop + 30);

ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("1", x1, yBot + 20);
ctx.textAlign = "left";
ctx.fillText("0", x0, yBot + 20);

out.note = "gamma " + gam.toFixed(2) + "  |  reaching the ground: " +
  fRel.toExponential(2) + " with dilation, " + fCla.toExponential(2) + " without";
